ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr) {
    ssize_t ret = 0;
    int error = 0;

    if (tty->flags & TTY_IO_ERROR)
        return -EIO;

    if (tty->termios.c_lflag & ECHO) {
        // Process pending echoed characters
        process_echoes(tty);
    }

    while (ret < (ssize_t)nr) {
        if (signal_pending(current)) {
            error = -EINTR;
            break;
        }

        if (file->f_flags & O_NONBLOCK) {
            if (tty->driver->chars_in_buffer(tty) > 0) {
                error = -EAGAIN;
                break;
            }
        }

        if (tty->output_blocked) {
            wait_for_space(tty);
            continue;
        }

        // Determine the number of bytes to write in this iteration
        size_t chars_to_write = min(tty->driver->chars_in_buffer(tty), nr - ret);

        if (chars_to_write == 0)
            break;

        if (tty->termios.c_oflag & ONLCR) {
            // Process output characters with new-line translation
            for (size_t i = 0; i < chars_to_write; ++i) {
                if (buf[ret + i] == '\n') {
                    // Translate '\n' into '\r\n' if ONLCR is set
                    if (tty->driver->write(tty, "\r", 1) < 1)
                        break;
                }
                if (tty->driver->write(tty, buf + ret + i, 1) < 1)
                    break;
            }
        } else {
            // Write directly to the tty
            size_t bytes_written = tty->driver->write(tty, buf + ret, chars_to_write);
            if (bytes_written <= 0) {
                error = (bytes_written < 0) ? bytes_written : -EIO;
                break;
            }
            ret += bytes_written;
        }
    }

    if (ret == 0 && error == 0)
        error = -EAGAIN;

    return (error) ? error : ret;
}

ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr) {
    ssize_t ret = 0;
    int count;
    unsigned int cflag;

    if (tty->driver->write == NULL)
        return -EINVAL;

    if (tty_jobctl(tty, file)) {
        wait_for_jobctrl(tty);
        if (tty_hung_up())
            return -EIO;
    }

    down(&tty->sem);

    while (nr > 0) {
        count = tty->driver->write(tty, file, buf, nr);
        if (count < 0) {
            ret = count;
            break;
        }

        if (count == 0) {
            if (file->f_flags & O_NONBLOCK) {
                ret = -EAGAIN;
                break;
            }

            if (signal_pending(current)) {
                ret = -ERESTARTSYS;
                break;
            }

            schedule();
            continue;
        }

        buf += count;
        nr -= count;
        ret += count;
    }

    up(&tty->sem);
    return ret;
}

ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr) {
    ssize_t count = 0;
    int start;

    if (tty_jobctrl_enabled(tty) && !tty_is_current_foreground(tty))
        return -EIO;

    down_read(&tty->sem);

    while (count < nr) {
        if (signal_pending(current)) {
            if (file->f_flags & O_NONBLOCK)
                return -EAGAIN;
            else if (current->signal->sigpending)
                break;
        }

        start = tty->output_start;

        if (start != tty->output_end) {
            unsigned char echoed;
            echoed = tty_get_echo_char(tty);
            if (echoed)
                tty_putchar(tty, echoed);
        }

        if (tty->output_processing_enabled) {
            size_t bytes_to_process = nr - count;
            size_t processed = tty_process_output(tty, buf + count, bytes_to_process);
            count += processed;
        } else {
            size_t bytes_to_write = nr - count;
            ssize_t written = tty_write_raw(tty, buf + count, bytes_to_write);
            if (written < 0)
                break;
            count += written;
        }

        if (file->f_flags & O_NONBLOCK && count == 0)
            return -EAGAIN;
    }

    up_read(&tty->sem);
    return count;
}

ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr) {
    ssize_t count = 0;
    int i;

    down_read(&tty->sem);

    for (i = 0; i < nr; i++) {
        if (signal_pending(current)) {
            count = -EINTR;
            break;
        }

        if (tty->icanon && (tty->output_block_length > 0)) {
            process_output_block(tty, buf + i, nr - i);
            i += tty->output_block_length - 1;
        }

        if (tty->lflag & ECHO && (tty->echo_flags & ECHO_CHAR)) {
            echo_char(buf[i], tty);
        }

        if (tty->lflag & OPOST) {
            process_output_char(buf[i], tty);
        } else {
            write_char(buf[i], tty);
        }

        count++;
    }

    up_read(&tty->sem);
    return count;
}

ssize_t tty_write(struct tty_struct *tty, struct file *file, const unsigned char *buf, size_t nr) {
    ssize_t count = 0;
    size_t orig_nr = nr;
    int must_block = file->f_flags & O_NONBLOCK;

    if (tty->flags & (1 << TTY_IO_ERROR))
        return -EIO;

    if (tty->flags & (1 << TTY_THROTTLED))
        return -EAGAIN;

    while (count < nr) {
        int c;
        unsigned long flags;

        if (current->signal->tty == tty && current->signal->asleep) {
            spin_lock_irqsave(&tty->lock, flags);
            if (current->signal->asleep) {
                current->signal->asleep = NULL;
                wake_up_interruptible(&tty->read_wait);
            }
            spin_unlock_irqrestore(&tty->lock, flags);
        }

        if (tty->driver->chars_in_buffer(tty)) {
            c = tty->driver->chars_in_buffer(tty);
            if (c)
                schedule_timeout_uninterruptible(c);
        }

        if (signal_pending(current))
            break;

        if (tty->driver->write(tty, (unsigned char *)buf + count, nr - count) < 0) {
            if (must_block)
                return -EAGAIN;
            schedule_timeout_uninterruptible(HZ / 10);
            continue;
        }

        count += nr - count;
        nr = 0;
        break;
    }

    if (count == 0 && nr == orig_nr)
        return -EAGAIN;

    return count;
}
